import type { ReactNode } from "react";

/**
 * Ornement des titres.
 *
 * Au centre, un motif propre au territoire ; de part et d'autre, un trait
 * bordé de petites feuilles de vigne. Sur les pages qui ne parlent pas d'un
 * territoire en particulier, le motif central est la grappe.
 *
 * D'où viennent ces dessins
 * -------------------------
 * Ce sont des illustrations fournies par Antoine, vectorisées : l'image est
 * binarisée, ses contours suivis au marching squares, puis simplifiés. Les
 * emblèmes des territoires sont des dessins ombrés, pas du trait : ils sont
 * donc découpés en trois niveaux de gris, rendus en trois opacités du même
 * vert, faute de quoi ils s'aplatissaient en pâtés.
 *
 * Les petites feuilles de la frise sont découpées dans le dessin de la grappe
 * lui-même, pour que la frise et le motif central aient la même main.
 *
 * Pourquoi `fill-rule="evenodd"`
 * ------------------------------
 * Le trait est une forme pleine et non un contour. Sans cette règle,
 * l'intérieur des traits se remplirait et le dessin deviendrait un bloc.
 * `fill="currentColor"` suffit alors à lui donner le vert de la section, et
 * aucun aplat de fond n'est nécessaire : l'ornement tient sur n'importe quel
 * fond.
 *
 * Taille
 * ------
 * Les motifs sont calibrés pour 110 px de haut au plus et 172 px de large au
 * plus — les Pyrénées, très larges, sont donc plus basses. En dessous d'une
 * centaine de pixels, les nervures et les grains commencent à se refermer.
 */
export type Embleme = "grappe" | "perigord" | "landes" | "pyrenees" | "gascogne";

/** Le territoire d'une page de destination décide de son motif. */
export function emblemeDeRegion(slug: string): Embleme {
  if (slug === "perigord") return "perigord";
  if (slug === "landes") return "landes";
  if (slug === "pyrenees-atlantiques") return "pyrenees";
  if (slug === "gascogne-armagnac") return "gascogne";
  // Bordeaux-Médoc garde la grappe : c'est déjà son emblème.
  return "grappe";
}

