export function Ornament({
  className = "",
  tone = "dark",
  embleme = "grappe",
}: {
  className?: string;
  /** `light` sur les fonds sombres. */
  tone?: "dark" | "light";
  embleme?: Embleme;
}) {
  const motif = MOTIFS[embleme];

  return (
    <svg
      aria-hidden
      viewBox={motif.vb}
      width={motif.largeur}
      height={motif.hauteur}
      className={`h-auto max-w-full ${tone === "light" ? "text-feuille-400" : "text-feuille-600"}${className ? ` ${className}` : ""}`}
    >
      {motif.corps}
    </svg>
  );
}
